export class Order {
  #lines: OrderLine[] = [];

  get lines(): readonly OrderLine[] {
    return this.#lines;
  }

  addLine(line: OrderLine): void {
    if (this.#lines.length === 50) {
      throw new OrderRuleError('An order has at most 50 lines');
    }
    this.#lines.push(line);
  }
}

